import {DEFAULTS,normalizeSettings,calculate} from './calc.mjs';
const $=id=>document.getElementById(id);let pinned=true;
const invoke=(cmd,args)=>window.__TAURI__?.core.invoke(cmd,args)||Promise.reject(Error('仅桌面版支持'));
function tick(){let settings=DEFAULTS,saved=false,hidden=false;try{const raw=localStorage.getItem('salary-cheer-v1');if(raw){settings=normalizeSettings(JSON.parse(raw));saved=true;}hidden=localStorage.getItem('salary-cheer-hidden')==='true';}catch{}const r=calculate(settings),t=Math.ceil(r.remaining),h=Math.floor(t/3600),m=Math.floor(t%3600/60),s=t%60;document.body.classList.toggle('hidden',hidden);$('hide-money').setAttribute('aria-label',hidden?'显示金额':'隐藏金额');$('sample').textContent=saved?'':'示例';$('status').textContent=r.status;$('income').textContent='¥'+r.earned.toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});$('fill').style.width=r.progress*100+'%';$('percent').textContent=(r.progress*100).toFixed(1)+'%';$('left').textContent=!r.active?'今天休息':r.status==='已下班'?'快乐下班 ✓':`下班 ${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;$('rate').textContent=`每小时 ¥${r.hour.toFixed(2)}`;}
$('close').onclick=()=>invoke('hide_widget').catch(()=>{});$('open').onclick=()=>invoke('open_main').catch(()=>{});$('pin').onclick=async()=>{try{await invoke('pin_widget',{pinned:!pinned});pinned=!pinned;$('pin').title=pinned?'取消置顶':'置顶';$('pin').setAttribute('aria-label',$('pin').title);$('pin').style.opacity=pinned?'1':'.4';}catch{}};$('hide-money').onclick=()=>{try{localStorage.setItem('salary-cheer-hidden',localStorage.getItem('salary-cheer-hidden')==='true'?'false':'true');tick();}catch{}};tick();setInterval(tick,1000);window.addEventListener('storage',tick);document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});
